function chipModo(e){return'<span class="chip '+esc(e)+'">'+esc(t("modo."+e))+"</span>"}function esFuenteTop(e){return!!(e&&String(e).indexOf("top:")===0)}function medallaTop(e){var s=parseInt(e,10);return s===1?"\u{1F3C6}":s===2?"\u{1F948}":s===3?"\u{1F949}":s>=4?'<span class="medalla-num">#'+s+"</span>":"\u{1F3C5}"}function chipFuente(e,s){if(!e)return"";var a=String(e);return a.indexOf("top:live:")===0?'<span class="chip top">'+medallaTop(s)+" "+esc(t("builds.top_semana"))+"</span>":a.indexOf("top:was:")===0||a.indexOf("top:")===0?'<span class="chip top ex">'+medallaTop(s)+" "+esc(t("builds.ex_top"))+"</span>":'<span class="chip referencia">'+esc(t("builds.referencia"))+"</span>"}function chipVotos(e){var s=e.likes||0,a=e.dislikes||0;return!s&&!a?"":'<span class="chip votos" title="'+esc(t("builds.votos"))+'">\u{1F44D} '+s+(a?" \xB7 \u{1F44E} "+a:"")+"</span>"}function urlFotoPj(e){return/^https:\/\/(profileimg\.plaync\.com|assets\.playnccdn\.com)\//.test(e||"")?e:""}function arteBuild(e){var s=e.personaje||{},a=s.ficha||{},r=urlFotoPj(e.imagen)||urlFotoPj(s.imagen)||urlFotoPj(a.imagen);return r?{src:r,foto:!0}:{src:"icons/clases/"+e.clase+"-arte.webp",foto:!1}}function fmtPoder(e){if(e=Number(e),!isFinite(e)||e<=0)return"";if(e>=1e3){var s=Math.round(e/100)/10;return(s%1?s.toFixed(1):String(Math.round(s)))+"K"}return fmtNum(e)}function tarjetaBuildTop(e){var s=claseInfo(e.clase),a=e.top||{},r=a.rank,p=a.nombre||e.nombre,c=a.semana,l=arteBuild(e),n=a.poder!=null?a.poder:null,o=a.nivel_objeto!=null?a.nivel_objeto:null,u="";(n!=null||o!=null)&&(u='<div class="top-stats">'+(n!=null?'<span class="top-stat poder"><em>'+esc(t("tops.orden_poder"))+"</em><b>"+esc(fmtPoder(n))+"</b></span>":"")+(o!=null?'<span class="top-stat ilvl"><em>'+esc(t("espia.ilvl"))+"</em><b>"+esc(fmtNum(o))+"</b></span>":"")+"</div>");var i=[];return a.servidor&&i.push(a.servidor),c&&i.push(c),'<a class="tarjeta-build tarjeta-top con-arte" href="build.html?id='+e.id+'"><img class="tarjeta-arte'+(l.foto?" foto-pj":"")+'" src="'+esc(l.src)+'" alt="" loading="lazy"><span class="medalla-top" aria-hidden="true">'+medallaTop(r)+'</span><div class="cab"><img src="icons/clases/'+e.clase+'.webp" alt=""><div><b>'+esc(p)+"</b><small>"+esc(tr(s))+(i.length?" \xB7 "+esc(i.join(" \xB7 ")):"")+"</small></div></div>"+u+'<div class="chips">'+chipFuente(e.fuente,r)+chipVotos(e)+"</div></a>"}function tarjetaBuild(e){var s=claseInfo(e.clase);if(esFuenteTop(e.fuente))return tarjetaBuildTop(e);var a=(e.modo?chipModo(e.modo):"")+chipFuente(e.fuente)+chipVotos(e),r=arteBuild(e);return'<a class="tarjeta-build con-arte" href="build.html?id='+e.id+'"><img class="tarjeta-arte'+(r.foto?" foto-pj":"")+'" src="'+esc(r.src)+'" alt="" loading="lazy"><div class="cab"><img src="icons/clases/'+e.clase+'.webp" alt=""><div><b>'+esc(e.nombre)+"</b><small>"+esc(tr(s))+" \xB7 "+esc(t("builds.por"))+" "+esc(e.autor)+'</small></div></div><div class="chips">'+a+'</div><small class="tarjeta-fecha">'+esc(t("builds.actualizada"))+" "+esc(fecha(e.actualizado))+"</small></a>"}function selectorClases(e,s){return'<div class="selector-clase">'+CLASES_INFO.map(function(a){return'<label><input type="radio" name="'+e+'" value="'+a.id+'"'+(a.id===s?" checked":"")+'><img src="icons/clases/'+a.id+'.webp" alt=""><span>'+esc(tr(a))+"</span></label>"}).join("")+"</div>"}function opcionesModo(e,s){return(s?'<option value="">'+esc(t("modo.todos"))+"</option>":"")+["pve","pvp","farm","otro"].map(function(a){return'<option value="'+a+'"'+(a===e?" selected":"")+">"+esc(t("modo."+a))+"</option>"}).join("")}function idYoutube(e){var s=String(e).match(/(?:v=|youtu\.be\/|shorts\/)([\w-]{6,})/);return s&&s[1]}function videosHTML(e){return'<div class="videos">'+(e||[]).map(function(s){var a=idYoutube(s);return a?'<iframe src="https://www.youtube-nocookie.com/embed/'+esc(a)+'" loading="lazy" allowfullscreen allow="accelerometer; encrypted-media; gyroscope; picture-in-picture"></iframe>':""}).join("")+"</div>"}
